import { answerQuestion } from '../../src/lib/engine';
for (const q of ['is it too late to start saving at 35?', 'how do I raise my credit score?', 'should I buy bitcoin?']) {
  const r = answerQuestion(q);
  console.log(q, '→', r.kind, 'intent' in r ? r.intent.id : '', r.kind === 'answer' ? `${r.intent.bestMoment.label} ${r.intent.bestMoment.startSec}-${r.intent.bestMoment.endSec}` : '', r.kind === 'out-of-scope' ? r.topic.topic + ' nearest w' + r.topic.nearest?.week : '');
}
